"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { EnrichedDishCard } from "@/components/dishes/EnrichedDishCard";
import { Scan, MenuItem } from "@/types/menu";
import { EnrichedDish } from "@/types/menu";
import { getOfflineScans } from "@/lib/offline-db";

interface CachedResult {
  scan: Partial<Scan>;
  items: MenuItem[];
  agent_summary?: string | null;
  enriched?: boolean;
  cached_at: number;
}

export default function ResultsPage() {
  const params = useParams();
  const router = useRouter();
  const [scan, setScan] = useState<Scan | null>(null);
  const [items, setItems] = useState<MenuItem[]>([]);
  const [agentSummary, setAgentSummary] = useState<string | null>(null);
  const [enrichedDishes, setEnrichedDishes] = useState<EnrichedDish[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadResults = async () => {
      const scanId = params.id as string;

      // Try sessionStorage first (fastest — set by scan page before redirect)
      try {
        const cached = sessionStorage.getItem(`scan-${scanId}`);
        if (cached) {
          const data: CachedResult = JSON.parse(cached);
          setScan(data.scan as Scan);
          setItems(data.items);
          setAgentSummary(data.agent_summary || null);
          if (data.enriched && data.items.length > 0) {
            setEnrichedDishes(data.items.map((item: MenuItem) => ({
              id: item.id,
              name: item.name,
              description: item.description,
              ai_description: item.description,
              price: item.price,
              category: item.category,
              origin: (item as unknown as Record<string, string>).origin || "",
              dietary_tags: (item as unknown as Record<string, string[]>).dietary_tags || [],
              images: item.image_url ? [item.image_url] : [],
              confidence: item.confidence,
            })));
          }
          setLoading(false);
          return;
        }
      } catch {
        // sessionStorage unavailable
      }

      // Try IndexedDB (offline-db) next
      try {
        const offlineScans = await getOfflineScans();
        const cachedScan = offlineScans.find((s: Record<string, unknown>) => s.id === scanId) as unknown as CachedResult | undefined;
        if (cachedScan && cachedScan.items && cachedScan.items.length > 0) {
          setScan(cachedScan.scan as Scan);
          setItems(cachedScan.items);
          setAgentSummary(cachedScan.agent_summary || null);
          if (cachedScan.enriched && cachedScan.items.length > 0) {
            setEnrichedDishes(cachedScan.items.map((item: MenuItem) => ({
              id: item.id,
              name: item.name,
              description: item.description,
              ai_description: item.description,
              price: item.price,
              category: item.category,
              origin: (item as unknown as Record<string, string>).origin || "",
              dietary_tags: (item as unknown as Record<string, string[]>).dietary_tags || [],
              images: item.image_url ? [item.image_url] : [],
              confidence: item.confidence,
            })));
          }
          setLoading(false);
          return;
        }
      } catch {
        // IndexedDB unavailable
      }

      // Fallback to API
      try {
        const res = await fetch(`/api/scan/${scanId}`);
        const data = await res.json();

        if (!res.ok) {
          throw new Error(data.error || "Failed to load results");
        }

        setScan(data.scan);
        setItems(data.items);
        setAgentSummary(data.agent_summary || null);
        if (data.enriched && data.items && data.items.length > 0) {
          setEnrichedDishes(
            data.items.map((item: MenuItem) => ({
              id: item.id,
              name: item.name,
              description: item.description,
              ai_description: item.description,
              price: item.price,
              category: item.category,
              origin: (item as unknown as Record<string, string>).origin || "",
              dietary_tags: (item as unknown as Record<string, string[]>).dietary_tags || [],
              images: item.image_url ? [item.image_url] : [],
              confidence: item.confidence,
            }))
          );
        }
      } catch (err: unknown) {
        const message = err instanceof Error ? err.message : "Failed to load results";
        setError(message);
      } finally {
        setLoading(false);
      }
    };

    loadResults();
  }, [params.id]);

  const hasEnriched = enrichedDishes.length > 0;

  if (loading) {
    return (
      <div className="min-h-screen flex flex-col">
        <header className="border-b">
          <div className="container mx-auto px-4 py-4 flex items-center justify-between">
            <h1 className="text-2xl font-bold">MenuLens</h1>
            <Button variant="ghost" onClick={() => router.push("/")}>
              Home
            </Button>
          </div>
        </header>
        <main className="flex-1 container mx-auto px-4 py-8 max-w-4xl">
          <div className="space-y-6">
            <Skeleton className="h-8 w-64" />
            <Card className="p-6">
              <div className="space-y-3">
                <Skeleton className="h-4 w-full" />
                <Skeleton className="h-4 w-5/6" />
                <Skeleton className="h-4 w-2/3" />
              </div>
            </Card>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {[1, 2, 3].map((i) => (
                <Card key={i} className="overflow-hidden">
                  <Skeleton className="aspect-video" />
                  <div className="p-4 space-y-2">
                    <Skeleton className="h-6 w-3/4" />
                    <Skeleton className="h-4 w-full" />
                    <Skeleton className="h-4 w-1/2" />
                  </div>
                </Card>
              ))}
            </div>
          </div>
        </main>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex flex-col">
        <header className="border-b">
          <div className="container mx-auto px-4 py-4 flex items-center justify-between">
            <h1 className="text-2xl font-bold">MenuLens</h1>
            <Button variant="ghost" onClick={() => router.push("/")}>
              Home
            </Button>
          </div>
        </header>
        <main className="flex-1 flex items-center justify-center">
          <Card className="p-8 text-center space-y-4">
            <div className="text-5xl">Error</div>
            <h2 className="text-xl font-semibold">Error Loading Results</h2>
            <p className="text-muted-foreground">{error}</p>
            <Button onClick={() => router.push("/scan")}>Scan Again</Button>
          </Card>
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col">
      <header className="border-b">
        <div className="container mx-auto px-4 py-4 flex items-center justify-between">
          <h1 className="text-2xl font-bold">MenuLens</h1>
          <nav className="flex gap-2">
            <Button variant="ghost" onClick={() => router.push("/scan")}>
              New Scan
            </Button>
            <Button variant="ghost" onClick={() => router.push("/")}>
              Home
            </Button>
          </nav>
        </div>
      </header>

      <main className="flex-1 container mx-auto px-4 py-8 max-w-4xl">
        <div className="space-y-6">
          <div>
            <h2 className="text-3xl font-bold">
              {hasEnriched ? enrichedDishes.length : items.length} dishes found
            </h2>
            <p className="text-muted-foreground mt-1">
              {scan?.created_at &&
                `Scanned on ${new Date(scan.created_at).toLocaleDateString()}`}
              {hasEnriched && " — Researched by AI Agent"}
            </p>
          </div>

          {agentSummary && (
            <Card className="p-6 bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-950/50 dark:to-indigo-950/50 border-blue-200 dark:border-blue-800">
              <div className="flex items-start gap-3">
                <div className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center text-white text-sm font-bold shrink-0">
                  AI
                </div>
                <div>
                  <h3 className="font-semibold text-blue-900 dark:text-blue-100 mb-2">
                    AI Food Expert Review
                  </h3>
                  <p className="text-blue-800 dark:text-blue-200 leading-relaxed whitespace-pre-line">
                    {agentSummary}
                  </p>
                </div>
              </div>
            </Card>
          )}

          {hasEnriched ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {enrichedDishes.map((dish) => (
                <EnrichedDishCard key={dish.id} dish={dish} />
              ))}
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {items.map((item) => (
                <EnrichedDishCard
                  key={item.id}
                  dish={{
                    id: item.id,
                    name: item.name,
                    description: item.description,
                    price: item.price,
                    category: item.category,
                    dietary_tags: [],
                    images: item.image_url ? [item.image_url] : [],
                    confidence: item.confidence,
                  }}
                />
              ))}
            </div>
          )}

          {items.length === 0 && enrichedDishes.length === 0 && (
            <Card className="p-8 text-center space-y-4">
              <div className="text-5xl">No dishes found</div>
              <h3 className="text-xl font-semibold">No dishes found</h3>
              <p className="text-muted-foreground">
                The AI couldn&apos;t identify any dishes. Try a clearer image.
              </p>
              <Button onClick={() => router.push("/scan")}>Try Again</Button>
            </Card>
          )}
        </div>
      </main>
    </div>
  );
}
