"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import Image from "next/image";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { EnrichedDish } from "@/types/menu";

interface DishDetails {
  detailed_description: string;
  ingredients: string[];
  preparation: string;
  serving_suggestions: string;
  fun_fact: string;
}

interface EnrichedDishCardProps {
  dish: EnrichedDish;
}

export function EnrichedDishCard({ dish }: EnrichedDishCardProps) {
  const [images, setImages] = useState<string[]>(dish.images || []);
  const [loading, setLoading] = useState(dish.images.length === 0);
  const [selectedImage, setSelectedImage] = useState(0);
  const [failedImages, setFailedImages] = useState<Set<number>>(new Set());
  const [expanded, setExpanded] = useState(false);
  const [details, setDetails] = useState<DishDetails | null>(null);
  const [detailsLoading, setDetailsLoading] = useState(false);
  const [detailsFetched, setDetailsFetched] = useState(false);

  const fetchedRef = useRef<string | null>(null);
  const prevImagesRef = useRef<string[]>(dish.images);

  const handleImageError = useCallback((index: number) => {
    setFailedImages((prev) => {
      const next = new Set(prev);
      next.add(index);
      return next;
    });
    const nextValid = images.findIndex((_, i) => i > index && !failedImages.has(i));
    if (nextValid !== -1) {
      setSelectedImage(nextValid);
    }
  }, [images, failedImages]);

  useEffect(() => {
    setFailedImages(new Set());
    setSelectedImage(0);
  }, [images]);

  useEffect(() => {
    if (dish.images.length > 0) {
      if (JSON.stringify(prevImagesRef.current) !== JSON.stringify(dish.images)) {
        setImages(dish.images);
        fetchedRef.current = null;
      }
      prevImagesRef.current = dish.images;
      return;
    }
    if (fetchedRef.current === dish.name) return;
    fetchedRef.current = dish.name;

    const fetchImages = async () => {
      try {
        const res = await fetch(`/api/images/${encodeURIComponent(dish.name)}`);
        const data = await res.json();
        const urls = (data.images || [])
          .slice(0, 3)
          .map((img: { url: string }) => img.url);
        setImages(urls);
      } catch {
        // silently fail
      } finally {
        setLoading(false);
      }
    };

    fetchImages();
  }, [dish.name, dish.images]);

  useEffect(() => {
    if (!expanded || detailsFetched) return;

    const fetchDetails = async () => {
      setDetailsLoading(true);
      try {
        const res = await fetch("/api/dishes/details", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            dishName: dish.name,
            category: dish.category,
            origin: dish.origin,
            description: dish.ai_description || dish.description,
          }),
        });
        if (res.ok) {
          const data = await res.json();
          setDetails(data);
        }
      } catch {
        // silently fail
      } finally {
        setDetailsLoading(false);
        setDetailsFetched(true);
      }
    };

    fetchDetails();
  }, [expanded, detailsFetched, dish.name, dish.category, dish.origin, dish.ai_description, dish.description]);

  const categoryColors: Record<string, string> = {
    appetizer: "bg-orange-100 text-orange-800",
    entree: "bg-blue-100 text-blue-800",
    dessert: "bg-pink-100 text-pink-800",
    drink: "bg-green-100 text-green-800",
    side: "bg-yellow-100 text-yellow-800",
    soup: "bg-purple-100 text-purple-800",
    salad: "bg-emerald-100 text-emerald-800",
    other: "bg-gray-100 text-gray-800",
  };

  const visibleImages = images.filter((_, i) => !failedImages.has(i));

  return (
    <Card
      className="overflow-hidden cursor-pointer transition-shadow hover:shadow-md"
      onClick={() => setExpanded((prev) => !prev)}
    >
      <div className="aspect-video relative bg-muted">
        {loading ? (
          <Skeleton className="w-full h-full" />
        ) : visibleImages.length > 0 ? (
          <>
            <Image
              src={visibleImages[0]}
              alt={dish.name}
              fill
              sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw"
              className="object-cover"
              onError={() => handleImageError(selectedImage)}
            />
            {visibleImages.length > 1 && (
              <div className="absolute bottom-2 left-2 flex gap-1">
                {visibleImages.slice(0, 5).map((_, i) => (
                  <button
                    key={i}
                    onClick={(e) => {
                      e.stopPropagation();
                      setSelectedImage(i);
                    }}
                    className={`w-2 h-2 rounded-full ${
                      i === selectedImage ? "bg-white" : "bg-white/50"
                    }`}
                  />
                ))}
              </div>
            )}
          </>
        ) : (
          <div className="w-full h-full flex items-center justify-center text-4xl">
            🍽️
          </div>
        )}
      </div>

      <div className="p-4 space-y-2">
        <div className="flex items-start justify-between gap-2">
          <h3 className="font-semibold text-lg">{dish.name}</h3>
          <div className="flex items-center gap-2">
            {dish.price && (
              <span className="font-bold text-lg whitespace-nowrap">
                ${dish.price.toFixed(2)}
              </span>
            )}
            <svg
              className={`w-4 h-4 text-muted-foreground transition-transform duration-200 ${
                expanded ? "rotate-180" : ""
              }`}
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth={2}
            >
              <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
            </svg>
          </div>
        </div>

        {!expanded && (dish.ai_description || dish.description) && (
          <p className="text-sm text-muted-foreground line-clamp-2">
            {dish.ai_description || dish.description}
          </p>
        )}

        {expanded && (
          <div className="space-y-3 text-sm">
            {detailsLoading ? (
              <div className="space-y-2">
                <Skeleton className="h-4 w-full" />
                <Skeleton className="h-4 w-5/6" />
                <Skeleton className="h-4 w-2/3" />
              </div>
            ) : details ? (
              <>
                <p className="text-muted-foreground leading-relaxed">
                  {details.detailed_description}
                </p>

                {details.ingredients.length > 0 && (
                  <div>
                    <span className="font-medium text-foreground">Ingredients: </span>
                    <span className="text-muted-foreground">
                      {details.ingredients.join(", ")}
                    </span>
                  </div>
                )}

                {details.preparation && (
                  <div>
                    <span className="font-medium text-foreground">Preparation: </span>
                    <span className="text-muted-foreground">{details.preparation}</span>
                  </div>
                )}

                {details.serving_suggestions && (
                  <div>
                    <span className="font-medium text-foreground">Serving: </span>
                    <span className="text-muted-foreground">{details.serving_suggestions}</span>
                  </div>
                )}

                {details.fun_fact && (
                  <div className="bg-muted/50 rounded-md p-2 mt-2">
                    <span className="font-medium text-foreground">Fun fact: </span>
                    <span className="text-muted-foreground">{details.fun_fact}</span>
                  </div>
                )}
              </>
            ) : (
              <>
                {(dish.ai_description || dish.description) && (
                  <p className="text-muted-foreground leading-relaxed">
                    {dish.ai_description || dish.description}
                  </p>
                )}
              </>
            )}

            <div className="flex flex-wrap gap-3 pt-2 border-t text-muted-foreground">
              {dish.category && (
                <span>
                  <span className="font-medium text-foreground">Category:</span>{" "}
                  {dish.category}
                </span>
              )}
              {dish.origin && (
                <span>
                  <span className="font-medium text-foreground">Cuisine:</span>{" "}
                  {dish.origin}
                </span>
              )}
              <span>
                <span className="font-medium text-foreground">Confidence:</span>{" "}
                {Math.round(dish.confidence * 100)}%
              </span>
            </div>
          </div>
        )}

        <div className="flex flex-wrap items-center gap-1.5">
          {dish.category && (
            <Badge
              variant="secondary"
              className={categoryColors[dish.category] || ""}
            >
              {dish.category}
            </Badge>
          )}

          {dish.dietary_tags.map((tag) => (
            <Badge key={tag} variant="outline" className="text-xs">
              {tag}
            </Badge>
          ))}

          {!expanded && (
            <span className="text-xs text-muted-foreground ml-auto">
              {Math.round(dish.confidence * 100)}%
            </span>
          )}
        </div>
      </div>
    </Card>
  );
}
